        int n = scanner.nextInt();
        String inputStr = scanner.next();
        String extendedStr = inputStr + "^";
        int totalLength = n + 1;
        char[] chars = new char[256];
        for (int i = 0; i < totalLength; i++) {
            chars[i] = extendedStr.charAt(i);
        }
        int insideFlag = 0;
        String currentSegment = "";
        for (int i = 0; i < totalLength; i++) {
            if (chars[i] == '(') {
                insideFlag = 1;
                chars[i] = '^';
                continue;
            } else if (chars[i] == ')') {
                insideFlag = 0;
                list2.add(currentSegment);
                chars[i] = '^';
                currentSegment = "";
            }
            if (insideFlag == 1) {
                currentSegment += chars[i];
                chars[i] = '^';
            }
        }
        currentSegment = "";
        for (int i = 0; i < totalLength; i++) {
            if (chars[i] == '^') {
                if (currentSegment.isEmpty()) continue;
                list1.add(currentSegment);
                currentSegment = "";
            } else {
                currentSegment += chars[i];
            }
        }
        int maxCount = 0;
        int totalWords = 0;
        for (String segment : list1) {
            String temp = segment + "_";
            int countLetters = 0;
            for (int j = 0; j < temp.length(); j++) {
                if (Character.isLetter(temp.charAt(j))) {
                    countLetters++;
                } else if (temp.charAt(j) == '_') {
                    maxCount = Math.max(maxCount, countLetters);
                    countLetters = 0;
                }
            }
        }
        int wordCount = 0;
        for (String segment : list2) {
            String temp = segment + "_";
            String wordBuilder = "";
            for (int j = 0; j < temp.length(); j++) {
                if (Character.isLetter(temp.charAt(j))) {
                    wordBuilder += temp.charAt(j);
                } else if (temp.charAt(j) == '_' && !wordBuilder.isEmpty()) {
                    wordBuilder = "";
                    wordCount++;
                }
            }
        }
        System.out.println(maxCount + " " + wordCount);
    }
}
